var setup=UnityEditor.SceneManagement.EditorSceneManager.GetSceneManagerSetup();var lines=new System.Collections.Generic.List<string>();try{foreach(var e in UnityEditor.EditorBuildSettings.scenes.Where(e=>e.path=="Assets/Scenes/Level01.unity")){var sc=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(e.path);var maps=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>()).Where(m=>m.name=="Ground — paint here").ToArray();if(maps.Length!=1)throw new System.Exception("Expected one ground map "+sc.name);var m=maps[0];var tc=m.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();tc.ProcessTilemapChanges();UnityEngine.Collider2D collider=m.GetComponent<UnityEngine.CompositeCollider2D>();if(collider==null)collider=tc;UnityEngine.Physics2D.SyncTransforms();int legacy=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.SpriteRenderer>(true)).Count(r=>r.name.StartsWith("Tube")||r.name.StartsWith("StairsBlock"));if(legacy!=0)throw new System.Exception("Legacy pillar/stair renderers remain");int count=0,missing=0,bad=0;foreach(var c in m.cellBounds.allPositionsWithin)if(m.HasTile(c)){count++;if(!collider.OverlapPoint(m.GetCellCenterWorld(c)))missing++;if(m.GetTransformMatrix(c)!=UnityEngine.Matrix4x4.identity)bad++;if(m.HasTile(c+UnityEngine.Vector3Int.up)){string sprite=UnityEditor.AssetDatabase.GetAssetPath(m.GetSprite(c));if(sprite.EndsWith("-top.png")||sprite.EndsWith("-tl.png")||sprite.EndsWith("-tr.png"))throw new System.Exception("Grass under covered cell "+c);}}if(missing>0||bad>0)throw new System.Exception(sc.name+" coverage="+missing+" transforms="+bad);lines.Add(sc.name+": one ground map; cells="+count+" missing="+missing+" nonidentity="+bad+" grid="+m.layoutGrid.cellSize+" origin="+m.layoutGrid.transform.position);
var go=new UnityEngine.GameObject("Temporary scene review camera");try{var camera=go.AddComponent<UnityEngine.Camera>();camera.orthographic=true;camera.orthographicSize=6;camera.clearFlags=UnityEngine.CameraClearFlags.SolidColor;camera.backgroundColor=new UnityEngine.Color(.15f,.18f,.2f);float x=12;float y=-.5f;camera.transform.position=new UnityEngine.Vector3(x,y,-20);var rt=new UnityEngine.RenderTexture(1200,800,24);var previous=UnityEngine.RenderTexture.active;camera.targetTexture=rt;camera.Render();UnityEngine.RenderTexture.active=rt;var tex=new UnityEngine.Texture2D(1200,800,UnityEngine.TextureFormat.RGB24,false);tex.ReadPixels(new UnityEngine.Rect(0,0,1200,800),0,0);tex.Apply();System.IO.File.WriteAllBytes("scripts/tilemap-pillars-20261110/"+sc.name+"-scene.png",tex.EncodeToPNG());camera.targetTexture=null;UnityEngine.RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}finally{UnityEngine.Object.DestroyImmediate(go);}
}}finally{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);UnityEditor.SceneManagement.EditorSceneManager.RestoreSceneManagerSetup(setup);System.IO.File.WriteAllLines("scripts/tilemap-pillars-20261110/verification.txt",lines);}return string.Join("\n",lines);
